using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must preserve it.
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // Breaking change 2: EF Core 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents use "Blog|1" format, so we must opt back in.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .HasJsonPropertyName("id")
                .ToJsonProperty("id");

            // Breaking change 3: Cosmos DB does not support indexing on arbitrary properties
            // directly via EF Core. HasIndex() now throws in EF Core 9.
            // Removed: entity.HasIndex(b => b.Name);
        });

        // Preserve the legacy "EntityType|Key" id format for existing data
        modelBuilder.Entity<Blog>().UsePropertyAccessMode(PropertyAccessMode.Property);
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Breaking change 4: EF Core 9 uses synchronous I/O by default which Cosmos SDK
        // disallows. Configure to allow it for the sync SaveChanges() in SyncJob.
        // Alternatively, migrate SyncJob to async.
    }
}
